import{_ as a,o as e,c as o,a5 as i}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"UC — Add Material Repository","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-12-add-material-repository/spec.md","filePath":"feature/content-task-workflow/3-6-12-add-material-repository/spec.md"}'),r={name:"feature/content-task-workflow/3-6-12-add-material-repository/spec.md"};function n(d,t,l,h,c,s){return e(),o("div",null,[...t[0]||(t[0]=[i(`<h1 id="uc-—-add-material-repository" tabindex="-1">UC — Add Material Repository <a class="header-anchor" href="#uc-—-add-material-repository" aria-label="Permalink to &quot;UC — Add Material Repository&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.6.12</td></tr><tr><td>Feature</td><td>Add Material Repository</td></tr><tr><td>Domain</td><td>Content &amp; Workflow (FR 3.6)</td></tr><tr><td>Role</td><td>CREATOR, CLIENT</td></tr><tr><td>Version</td><td>2.0 (V2 — nghiệp vụ mới, 2026-09-14)</td></tr><tr><td>Trạng thái tài liệu</td><td>Draft — BA confirmed, chưa code</td></tr></tbody></table><h2 id="_1-objective" tabindex="-1">1. Objective <a class="header-anchor" href="#_1-objective" aria-label="Permalink to &quot;1. Objective&quot;">​</a></h2><p>Upload file mới vào Material Repository.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>Là một Creator hoặc Client, tôi muốn upload ảnh/video mới vào Material Repository, để lưu trữ và dùng cho các Task sau này.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ul><li>Upload file (ảnh/video), chọn <code>type</code> (raw/retouched).</li><li>Client upload thường vào Brand Collection (không phải Material Repository thông thường) — phân biệt theo endpoint/UI.</li></ul><h2 id="_4-ui-ux" tabindex="-1">4. UI / UX <a class="header-anchor" href="#_4-ui-ux" aria-label="Permalink to &quot;4. UI / UX&quot;">​</a></h2><ul><li>Nút Upload trong <code>/workspaces/:id/materials</code>, hỗ trợ drag-drop multi-file.</li></ul><h2 id="_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" tabindex="-1">5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật) <a class="header-anchor" href="#_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" aria-label="Permalink to &quot;5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/v1/workspaces/{id}/materials</span></span>
<span class="line"><span>FormData: file, type</span></span>
<span class="line"><span>→ 201 { &quot;success&quot;: true, &quot;data&quot;: { &quot;id&quot;, &quot;url&quot;, &quot;type&quot; } }</span></span></code></pre></div><h2 id="_6-error-handling" tabindex="-1">6. Error Handling <a class="header-anchor" href="#_6-error-handling" aria-label="Permalink to &quot;6. Error Handling&quot;">​</a></h2><ul><li>File vượt dung lượng cho phép → 400 <code>FILE_TOO_LARGE</code>.</li><li>Định dạng không hỗ trợ → 400 <code>UNSUPPORTED_FILE_TYPE</code>.</li></ul><h2 id="_7-edge-cases" tabindex="-1">7. Edge Cases <a class="header-anchor" href="#_7-edge-cases" aria-label="Permalink to &quot;7. Edge Cases&quot;">​</a></h2><ul><li>Upload file trùng tên → tạo record mới, không overwrite (giữ cả 2 bản, đặt tên khác nhau tự động).</li></ul><h2 id="_8-definition-of-done" tabindex="-1">8. Definition of Done <a class="header-anchor" href="#_8-definition-of-done" aria-label="Permalink to &quot;8. Definition of Done&quot;">​</a></h2><ul><li>Upload thành công, hiển thị ngay trong list.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Không có.</li></ul><h2 id="tham-chieu-ba" tabindex="-1">Tham chiếu BA <a class="header-anchor" href="#tham-chieu-ba" aria-label="Permalink to &quot;Tham chiếu BA&quot;">​</a></h2><p><a href="./../../../BA/05-content-task-workflow.html">05-content-task-workflow.md</a></p>`,22)])])}const f=a(r,[["render",n]]);export{p as __pageData,f as default};
